insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"TOTAL_GTE_11","title":"¿Se irán a 11 o más carreras?","description":"Se corrige con el marcador final.","category":"total","difficulty":"hard","points":6,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"total_gte","n":11},"priority":0,"cooldown":2,"tags":["total"]},{"code":"TOTAL_GTE_12","title":"¿Habrá 12 o más carreras en total?","description":"Se corrige con el marcador final.","category":"total","difficulty":"hard","points":6,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"total_gte","n":12},"priority":0,"cooldown":2,"tags":["total"]},{"code":"TOTAL_GTE_13","title":"¿Habrá 13 o más carreras en total?","description":"Se corrige con el marcador final.","category":"total","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"total_gte","n":13},"priority":0,"cooldown":2,"tags":["total"]},{"code":"TOTAL_GTE_14","title":"¿Habrá 14 o más carreras en total?","description":"Se corrige con el marcador final.","category":"total","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"total_gte","n":14},"priority":0,"cooldown":2,"tags":["total"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;